#[test]
fn a_spent_move_books_the_pins_last_prompt_as_its_rewrite_and_its_own_decayed_burn() {
    let pool = || Pool {
        members: vec![("a", 0), ("b", 1)],
        shedding: Shedding {
            migrate_when_spent: true,
            burn_average_seconds: 1_800,
            ..Shedding::default()
        },
        ..Pool::default()
    };
    let s = tiered(pool());
    let moving_at = T + 1_000;
    // Folded one average before the move, so the priced rate reads at e^-1 on the new row's destination.
    let pin = PinRow {
        last_input_tokens: 813_365,
        burn_at: Some(moving_at - 1_800_000),
        ..burning("s1", "a", 40_000.0, true, T)
    };
    let spent = |st: &mut RoutingState| {
        st.set_share(ratio_pricer());
        st.record_sample("a", refreshing(1.0, T + 9 * HOUR, T + 9 * HOUR, T + 500), 0);
        st.record_sample("b", refreshing(0.2, T + 9 * HOUR, T + 9 * HOUR, T + 500), 0);
    };
    let mut st = loaded(vec![pin]);
    spent(&mut st);
    let req = SelectRequest {
        body_tokens: 200_000,
        ..request(&s, Some("s1"), "claude-sonnet-5", true, &[], moving_at)
    };
    assert_eq!(
        landed(select(&mut st, &s, &req, &mut rng()).0),
        ("b".into(), Some(MigrateReason::Spent))
    );
    let booked = st
        .reservation("r-1")
        .expect("the move books on its destination")
        .clone();
    assert_eq!(
        (booked.account_id.as_str(), booked.pin.as_ref()),
        ("b", Some(&pin_key("s1")))
    );
    assert!(
        close(booked.rewrite[FIVE_HOUR], 813_365.0 / 10_000_000.0),
        "the pin's last prompt as one five-minute write, not the body: {booked:?}"
    );
    assert!(close(booked.rewrite[SEVEN_DAY], 813_365.0 / 60_000_000.0));
    let decayed = (-1.0f64).exp();
    assert!(
        close(booked.burn[FIVE_HOUR], 40_000.0 / 10_000_000.0 * decayed),
        "the pin's own rate, decayed one average: {booked:?}"
    );
    assert!(close(
        booked.burn[SEVEN_DAY],
        40_000.0 / 60_000_000.0 * decayed
    ));
    // A pin never renewed with usage reads its context from the body, and a one-hour pin prices a one-hour write.
    let mut st = loaded(vec![PinRow {
        last_input_tokens: 0,
        cache_ttl_ms: 3_600_000,
        ..burning("s2", "a", 40_000.0, true, T)
    }]);
    spent(&mut st);
    let req = SelectRequest {
        body_tokens: 200_000,
        ..request(&s, Some("s2"), "claude-sonnet-5", true, &[], moving_at)
    };
    assert_eq!(
        landed(select(&mut st, &s, &req, &mut rng()).0),
        ("b".into(), Some(MigrateReason::Spent))
    );
    let booked = st.reservation("r-1").expect("the move books");
    assert!(
        close(booked.rewrite[FIVE_HOUR], 2.0 * 200_000.0 / 10_000_000.0),
        "the body's estimate as one one-hour write: {booked:?}"
    );
}

/// `tiered`'s terms over `ids` alone, so a case can hold one member off the tier or give one an end.
fn tier_terms(ids: &[&str]) -> Vec<SubscriptionTerm> {
    ids.iter()
        .map(|id| SubscriptionTerm {
            account_id: (*id).into(),
            since: None,
            trial_ends_at: None,
            cancellation: Cancellation::Off,
            tier: Some(TIER.into()),
            usage_based: false,
            plan: Some("max_20x".into()),
            plan_ended_at: None,
        })
        .collect()
}

/// `snapshot_over` with `terms`, for a pool wider than the builder's whose members price on a tier.
fn snapshot_over_terms(
    pool: Pool,
    extra: &[&str],
    terms: Vec<SubscriptionTerm>,
) -> RegistrySnapshot {
    let mut load = load_of(pool, &[]);
    let template = load.accounts[0].clone();
    for id in extra {
        load.accounts.push(AccountRow {
            id: (*id).into(),
            label: (*id).into(),
            ..template.clone()
        });
    }
    load.terms = terms;
    RegistrySnapshot::from_load(load, [0; 32], 0, 1)
}

/// `loaded` with the ratio pricer set, so a move prices its rewrite and burn through the case's own ratios.
fn priced(pins: Vec<PinRow>) -> RoutingState {
    let mut st = loaded(pins);
    st.set_share(ratio_pricer());
    st
}

/// A warm pin of `session` on `account` whose last prompt was 500 000 tokens, a twentieth of the 5-hour window as
/// one five-minute write on `TIER`, burning `input` tokens a second, which the ratio pricer reads as `input` ten
/// millionths of the 5-hour window a second.
fn gated_pin(session: &str, account: &str, input: f64) -> PinRow {
    PinRow {
        last_input_tokens: 500_000,
        ..burning(session, account, input, true, T)
    }
}

/// `a` spent with its reset hours out and `b` and `c` read at the given 5-hour utilizations with their resets three
/// hours out, so the spent rule moves `s1`'s pin and the gate reads both siblings.
fn gated_siblings(st: &mut RoutingState, b: f64, c: f64) {
    st.record_sample("a", refreshing(1.0, T + 9 * HOUR, T + 9 * HOUR, T - 500), 0);
    st.record_sample("b", refreshing(b, T + 3 * HOUR, T + 72 * HOUR, T - 500), 0);
    st.record_sample("c", refreshing(c, T + 3 * HOUR, T + 72 * HOUR, T - 500), 0);
}

fn gate_pool() -> Pool {
    Pool {
        members: vec![("a", 0), ("b", 1), ("c", 2)],
        ..Pool::default()
    }
}

/// `gate_pool` with `wind_down_minutes` before an end.
fn wind_down_gate_pool(wind_down_minutes: u32) -> Pool {
    Pool {
        failover: Failover {
            wind_down_minutes,
            ..Failover::default()
        },
        ..gate_pool()
    }
}

#[test]
fn with_no_fitting_destination_the_rewrite_only_candidate_with_the_longest_runway_takes_the_move() {
    let s = tiered(gate_pool());
    // 1 000 input tokens a second, a ten-thousandth of the window a second, overrun three hours on either sibling.
    let mut st = priced(vec![gated_pin("s1", "a", 1_000.0)]);
    gated_siblings(&mut st, 0.1, 0.2);
    let d = decide(
        &mut st,
        &s,
        &request(&s, Some("s1"), "claude-sonnet-5", true, &[], T),
        &mut rng(),
    );
    assert_eq!(
        landed(d.result.clone()),
        ("b".into(), Some(MigrateReason::Spent))
    );
    let fit = line(&d.record, "fit");
    assert_eq!(fit.verdict, "rewrite_only");
    assert_eq!(
        fact(line(&d.record, "move:spent"), "destinations"),
        &FactValue::List(vec!["b".into()]),
        "the longer runway alone"
    );
    // The move's line sits half the pin's 1.08 over the three hours under the ceiling, at 0.41. b: 0.26 of the window
    // left under it over the burn is 2 600 s, c: 0.16 left is 1 600 s, both short of the 10 800 s to the reset.
    assert_eq!(fact_of(fit, "runway_ms", "b"), &FactValue::Int(2_600_000));
    assert_eq!(fact_of(fit, "runway_ms", "c"), &FactValue::Int(1_600_000));
    for id in ["b", "c"] {
        assert_eq!(
            fact_of(fit, "verdict", id),
            &FactValue::Text("rewrite_only".into())
        );
    }
    assert_eq!(
        summary_facts(&d),
        vec![
            ("runway", FactValue::Int(2_600_000), Some("ms")),
            ("fit", FactValue::Text("rewrite only".into()), Some("text")),
        ]
    );
}

#[test]
fn a_sibling_with_room_under_the_band_reads_short_for_a_move_and_fits_a_placement() {
    let s = tiered(Pool {
        members: vec![("a", 0), ("b", 1)],
        ..Pool::default()
    });
    // s1 burns a ten-thousandth of the 5-hour window a second and holds no context, so neither read prices a
    // rewrite. As the pool's one warm pin it is a fresh session's prior as well, so the move and the placement read
    // one burn on b: 0.3 over the 3 000 s to b's reset, against the 0.39 that b's 0.56 leaves under the ceiling.
    let state = || {
        let mut st = priced(vec![PinRow {
            last_input_tokens: 0,
            ..burning("s1", "a", 1_000.0, true, T)
        }]);
        st.record_sample("a", refreshing(1.0, T + 9 * HOUR, T + 9 * HOUR, T - 500), 0);
        st.record_sample(
            "b",
            refreshing(0.56, T + 50 * MINUTE, T + 72 * HOUR, T - 500),
            0,
        );
        st
    };
    let moved = decide(
        &mut state(),
        &s,
        &request(&s, Some("s1"), "claude-sonnet-5", true, &[], T),
        &mut rng(),
    );
    assert_eq!(
        landed(moved.result.clone()),
        ("b".into(), Some(MigrateReason::Spent))
    );
    assert_eq!(
        candidate(&moved.record, "b").fit,
        Some("rewrite_only"),
        "the room covers 1.3 times the pin's burn, short of the band's 1.5, so the move reads b short"
    );
    let placed = decide(
        &mut state(),
        &s,
        &request(&s, None, "claude-sonnet-5", true, &[], T),
        &mut rng(),
    );
    assert_eq!(
        candidate(&placed.record, "b").fit,
        Some("fits"),
        "a fresh placement reads the same burn against the ceiling itself"
    );
}

#[test]
fn a_rewrite_only_candidate_with_a_window_past_its_reset_keeps_the_longest_runways_move() {
    let s = tiered(gate_pool());
    let mut st = priced(vec![gated_pin("s1", "a", 1_000.0)]);
    st.record_sample("a", refreshing(1.0, T + 9 * HOUR, T + 9 * HOUR, T - 500), 0);
    // Under the move's line, half the pin's burn to each horizon under the ceiling, b's 5-hour window binds at
    // 2 600 s, short of the 10 800 s to its reset, beside a week whose 46 900 s pass its reset two hours out. c's
    // 5-hour window binds at 1 600 s beside a week inside its reset.
    st.record_sample(
        "b",
        windows_with_resets((0.1, T + 3 * HOUR), (0.1, T + 2 * HOUR), T - 500),
        0,
    );
    st.record_sample(
        "c",
        refreshing(0.2, T + 3 * HOUR, T + 72 * HOUR, T - 500),
        0,
    );
    let d = decide(
        &mut st,
        &s,
        &request(&s, Some("s1"), "claude-sonnet-5", true, &[], T),
        &mut rng(),
    );
    assert_eq!(
        landed(d.result.clone()),
        ("b".into(), Some(MigrateReason::Spent))
    );
    let fit = line(&d.record, "fit");
    assert_eq!(fit.verdict, "rewrite_only");
    assert_eq!(
        fact(line(&d.record, "move:spent"), "destinations"),
        &FactValue::List(vec!["b".into()]),
        "the longer runway alone, the week past its reset leaving the order as it is"
    );
    assert_eq!(
        (fact_of(fit, "binding", "b"), fact_of(fit, "runway_ms", "b")),
        (
            &FactValue::Text("five_hour".into()),
            &FactValue::Int(2_600_000)
        )
    );
    assert_eq!(
        (fact_of(fit, "binding", "c"), fact_of(fit, "runway_ms", "c")),
        (
            &FactValue::Text("five_hour".into()),
            &FactValue::Int(1_600_000)
        )
    );
}

#[test]
fn under_priority_two_fitting_candidates_in_one_tier_take_the_longer_runway_without_a_draw() {
    let s = tiered(Pool {
        members: vec![("a", 0), ("b", 1), ("c", 1)],
        ..gate_pool()
    });
    let mut st = priced(vec![gated_pin("s1", "a", 100.0)]);
    // Under the move's line, half the pin's burn to each horizon under the ceiling, b: 0.546 of the window left over
    // the pin's burn is 54 600 s, c: 0.346 left is 34 600 s, both past the 10 800 s to the reset, and each week's
    // runway passes its reset 72 hours out: both runways read unbounded, while the computed figures still break the
    // tie.
    gated_siblings(&mut st, 0.3, 0.5);
    let d = decide(
        &mut st,
        &s,
        &request(&s, Some("s1"), "claude-sonnet-5", true, &[], T),
        &mut rng(),
    );
    assert_eq!(
        landed(d.result.clone()),
        ("b".into(), Some(MigrateReason::Spent))
    );
    let fit = line(&d.record, "fit");
    assert!(
        no_fact_of(fit, "runway_ms", "b") && no_fact_of(fit, "runway_ms", "c"),
        "{:?}",
        fit.facts
    );
    let pick = line(&d.record, "pick");
    assert_eq!(
        fact(pick, "ties"),
        &FactValue::List(vec!["b".into(), "c".into()]),
        "the tier is the strategy's tie"
    );
    assert_eq!(
        fact(pick, "by_runway"),
        &FactValue::List(vec!["b".into()]),
        "the longer runway breaks the tie"
    );
    assert_eq!(
        fact(pick, "drawn"),
        &FactValue::Bool(false),
        "one candidate is left after the runway, so nothing is drawn"
    );
}

#[test]
fn under_priority_a_runway_shown_unbounded_past_its_reset_still_breaks_the_tie_by_its_computed_figure(
) {
    let s = tiered(Pool {
        members: vec![("a", 0), ("b", 1), ("c", 1)],
        ..gate_pool()
    });
    let mut st = priced(vec![gated_pin("s1", "a", 100.0)]);
    st.record_sample("a", refreshing(1.0, T + 9 * HOUR, T + 9 * HOUR, T - 500), 0);
    // b, first in the tie, reaches the move's line, half the pin's burn to each horizon under the ceiling, past each
    // window's reset: 29 600 s on the 5-hour window against its reset three hours out, about 138 hours on the week
    // against its reset 72 hours out. c's 54 600 s on the 5-hour window pass its reset too, while its week's 76 000 s
    // stay inside the 72 hours. b's computed runway is the shorter.
    st.record_sample(
        "b",
        refreshing(0.55, T + 3 * HOUR, T + 72 * HOUR, T - 500),
        0,
    );
    st.record_sample(
        "c",
        windows_with_resets((0.3, T + 3 * HOUR), (0.8, T + 72 * HOUR), T - 500),
        0,
    );
    let d = decide(
        &mut st,
        &s,
        &request(&s, Some("s1"), "claude-sonnet-5", true, &[], T),
        &mut rng(),
    );
    assert_eq!(
        landed(d.result.clone()),
        ("c".into(), Some(MigrateReason::Spent))
    );
    let pick = line(&d.record, "pick");
    assert_eq!(
        fact(pick, "ties"),
        &FactValue::List(vec!["b".into(), "c".into()])
    );
    assert_eq!(
        fact(pick, "by_runway"),
        &FactValue::List(vec!["c".into()]),
        "the computed runway breaks the tie, so b's unbounded display never makes it the longest"
    );
    assert_eq!(fact(pick, "drawn"), &FactValue::Bool(false));
    let fit = line(&d.record, "fit");
    assert!(
        no_fact_of(fit, "runway_ms", "b") && no_fact_of(fit, "binding", "b"),
        "b's runway past every reset is shown unbounded: {:?}",
        fit.facts
    );
}

#[test]
fn under_pace_an_exact_score_tie_is_broken_by_the_runway() {
    let s = tiered(Pool {
        strategy: Strategy::Pace,
        members: vec![("a", 0), ("b", 1), ("c", 1)],
        ..gate_pool()
    });
    let mut st = priced(vec![gated_pin("s1", "a", 100.0)]);
    // b and c read one week, 0.1 with one reset, and no pin burns on either, so their scores tie exactly. Under the
    // move's line, half the pin's burn to the reset under the ceiling, c's 5-hour window at 0.3 leaves the pin
    // 54 600 s and b's at 0.5 leaves it 34 600 s.
    gated_siblings(&mut st, 0.5, 0.3);
    let d = decide(
        &mut st,
        &s,
        &request(&s, Some("s1"), "claude-sonnet-5", true, &[], T),
        &mut rng(),
    );
    assert_eq!(
        landed(d.result.clone()),
        ("c".into(), Some(MigrateReason::Spent))
    );
    let pick = line(&d.record, "pick");
    assert_eq!(
        fact_of(pick, "score", "b"),
        fact_of(pick, "score", "c"),
        "one week read alike scores alike"
    );
    assert_eq!(
        fact(pick, "ties"),
        &FactValue::List(vec!["b".into(), "c".into()])
    );
    assert_eq!(
        fact(pick, "by_runway"),
        &FactValue::List(vec!["c".into()]),
        "the longer runway breaks the exact tie"
    );
    assert_eq!(fact(pick, "drawn"), &FactValue::Bool(false));
}

#[test]
fn a_candidate_without_a_read_keeps_its_place_in_the_ties() {
    let s = tiered(Pool {
        members: vec![("b", 0), ("c", 0)],
        ..gate_pool()
    });
    let cap = s.pool("p").unwrap().failover.in_flight_cap;
    // A warm pin burning on b gives a fresh session's prior a burn, so b and c read different runways.
    let mut st = priced(vec![gated_pin("w", "b", 100.0)]);
    st.record_sample(
        "b",
        refreshing(0.3, T + 3 * HOUR, T + 72 * HOUR, T - 500),
        0,
    );
    st.record_sample(
        "c",
        refreshing(0.5, T + 3 * HOUR, T + 72 * HOUR, T - 500),
        0,
    );
    let _held: Vec<_> = ["b", "c"]
        .into_iter()
        .flat_map(|id| (0..cap).map(move |_| id))
        .map(|id| st.in_flight().dispatched(id, T - 1_000))
        .collect();
    // With every account at its cap the request is held, and the hold's choice is made with no read in hand.
    let d = decide(
        &mut st,
        &s,
        &request(&s, Some("fresh"), "claude-sonnet-5", true, &[], T),
        &mut rng(),
    );
    assert!(
        matches!(d.result, SelectResult::Held(_)),
        "every account at its cap holds the request: {:?}",
        d.result
    );
    assert_ne!(
        candidate(&d.record, "b").runway_ms,
        candidate(&d.record, "c").runway_ms,
        "the two runways differ, so a tiebreak would have narrowed the tier"
    );
    let pick = line(&d.record, "pick");
    assert_eq!(
        fact(pick, "ties"),
        &FactValue::List(vec!["b".into(), "c".into()])
    );
    assert!(
        pick.facts.iter().all(|f| f.key != "by_runway"),
        "no read narrows the ties: {:?}",
        pick.facts
    );
    assert_eq!(
        fact(pick, "drawn"),
        &FactValue::Bool(true),
        "the tier is drawn as it would be with no runway at all"
    );
}

#[test]
fn a_candidate_inside_its_wind_down_is_no_destination_for_a_move() {
    // Each account in `ids` ends two hours out, inside its three hours of wind-down.
    let ending = |ids: &[&str]| {
        let mut terms = tier_terms(&["a", "b", "c"]);
        for term in &mut terms {
            if ids.contains(&term.account_id.as_str()) {
                term.cancellation = Cancellation::On {
                    ends_at: Some(T + 2 * HOUR),
                };
            }
        }
        snapshot_with_terms(wind_down_gate_pool(180), terms)
    };
    let spent_a = || {
        let mut st = priced(vec![gated_pin("s1", "a", 100.0)]);
        gated_siblings(&mut st, 0.3, 0.3);
        st
    };
    let s = ending(&["c"]);
    let mut st = spent_a();
    let d = decide(
        &mut st,
        &s,
        &request(&s, Some("s1"), "claude-sonnet-5", true, &[], T),
        &mut rng(),
    );
    assert_eq!(
        landed(d.result.clone()),
        ("b".into(), Some(MigrateReason::Spent))
    );
    let fit = line(&d.record, "fit");
    assert_eq!(fit.verdict, "fits");
    assert_eq!(
        fact(line(&d.record, "move:spent"), "destinations"),
        &FactValue::List(vec!["b".into()]),
        "c fits by its figures and is in no order"
    );
    assert_eq!(
        fact_of(fit, "verdict", "c"),
        &FactValue::Text("ending".into())
    );
    assert_eq!(fact_of(fit, "end", "c"), &FactValue::Int(T + 2 * HOUR));
    assert_eq!(candidate(&d.record, "c").fit, Some("ending"));

    let s = ending(&["b", "c"]);
    let mut st = spent_a();
    let d = decide(
        &mut st,
        &s,
        &request(&s, Some("s1"), "claude-sonnet-5", true, &[], T),
        &mut rng(),
    );
    assert_eq!(
        landed(d.result.clone()),
        ("a".into(), None),
        "with every sibling ending the spent pin renews where it is"
    );
    let spent = line(&d.record, "move:spent");
    assert_eq!(spent.verdict, "no");
    assert_eq!(fact(spent, "no_destination"), &FactValue::Bool(true));
    assert_eq!(
        fact(spent, "ending"),
        &FactValue::List(vec!["b".into(), "c".into()])
    );
    let fit = line(&d.record, "fit");
    assert_eq!(fit.verdict, "none");
    for id in ["b", "c"] {
        assert_eq!(
            fact_of(fit, "verdict", id),
            &FactValue::Text("ending".into())
        );
    }
}

/// The decision on `s1`'s pin on a spent `a` at `now`, with `b` and `c` at 0.3 and `c` ending at `end` under
/// `wind_down_minutes`. By its figures `c` fits, its runway running far past its reset three hours out.
fn spent_beside_an_end(wind_down_minutes: u32, end: i64, now: i64) -> Decided {
    let mut terms = tier_terms(&["a", "b", "c"]);
    terms[2].cancellation = Cancellation::On { ends_at: Some(end) };
    let s = snapshot_with_terms(wind_down_gate_pool(wind_down_minutes), terms);
    let mut st = priced(vec![gated_pin("s1", "a", 100.0)]);
    gated_siblings(&mut st, 0.3, 0.3);
    decide(
        &mut st,
        &s,
        &request(&s, Some("s1"), "claude-sonnet-5", true, &[], now),
        &mut rng(),
    )
}

#[test]
fn the_fit_gate_reads_ending_inside_the_wind_down_and_fits_past_it() {
    let end = T + 120 * MINUTE;
    let d = spent_beside_an_end(30, end, T);
    assert_eq!(
        fact_of(line(&d.record, "fit"), "verdict", "c"),
        &FactValue::Text("fits".into()),
        "two hours out lies past a thirty-minute wind-down, so c reads its figures"
    );
    let d = spent_beside_an_end(180, end, T);
    let fit = line(&d.record, "fit");
    assert_eq!(
        (fact_of(fit, "verdict", "c"), fact_of(fit, "end", "c")),
        (&FactValue::Text("ending".into()), &FactValue::Int(end)),
        "inside a three-hour wind-down c reads ending, and the table states its end"
    );
    let d = spent_beside_an_end(120, end, T);
    assert_eq!(
        fact_of(line(&d.record, "fit"), "verdict", "c"),
        &FactValue::Text("ending".into()),
        "an end exactly the wind-down away is inside it"
    );
}

#[test]
fn wind_down_minutes_zero_leaves_no_rule_before_the_end() {
    let end = T + MINUTE;
    let d = spent_beside_an_end(0, end, T);
    assert_eq!(
        fact_of(line(&d.record, "fit"), "verdict", "c"),
        &FactValue::Text("fits".into()),
        "a minute before its end c reads its figures"
    );
    let d = spent_beside_an_end(0, end, end);
    let c = candidate(&d.record, "c");
    assert_eq!(
        (c.obstacle.as_ref().map(|o| o.name), c.fit),
        (Some("subscription_ended"), None),
        "at its end c is the obstacle, and no fit is read"
    );
}

