#[test]
fn a_request_that_waited_for_the_rewrite_is_not_held_for_the_slow_down() {
    let (off, on) = held_pools(120);
    // s1 builds its cycle on a, and b, where s0's turns stamped the ramp a burn average before, reads a factor of
    // about a half once s1 lands there too.
    let mut st = rounding(vec![
        burning("s1", "a", 15.0, true, T),
        burning("s0", "b", 15.0, true, T),
    ]);
    reading(&mut st, "a", 0.1, 2 * HOUR, T);
    reading(&mut st, "b", 0.80, 2 * HOUR, T);
    let at = T + 20 * SECOND;
    stamped(&mut st, &on, "s0", at);
    cycled(&mut st, &off, "s1", 10 * SECOND, T + 10 * SECOND);
    st.record_cooldown(cooled(
        "a",
        "model:claude-sonnet-5",
        T + 10 * MINUTE,
        "retry_after",
        "rate_limit",
    ));
    let moved = decide(&mut st, &on, &turn_of(&on, "r-1", at), &mut rng());
    assert_eq!(picked(&moved.result), "b");
    assert_eq!(left_of(&moved.result), Some("a"));
    let req = turn_of(&on, "r-2", at + 200);
    let d = decide(&mut st, &on, &req, &mut rng());
    let (_, hold) = held_on(&d);
    assert_eq!(
        (hold.reason, hold.waits_for.as_deref()),
        (HoldReason::Rewrite, Some("r-1")),
        "the rewrite's hold comes first"
    );
    let again = SelectRequest {
        seq: 2,
        now: at + 1_200,
        holds: vec![HoldFacts {
            held_ms: 1_000,
            ..hold
        }],
        ..req
    };
    let d = decide(&mut st, &on, &again, &mut rng());
    assert!(
        number(fact(line(&d.record, "move:shed"), "factor")) < 1.0,
        "b reads a slow-down"
    );
    let SelectResult::Selected(ref sel) = d.result else {
        panic!("the request that waited goes on, got {:?}", d.result)
    };
    assert!(sel.trace.renewed);
    assert_eq!(d.record.outcome.hold, None);
    assert_eq!(
        d.record.pin.as_ref().and_then(|pin| pin.slow_down_until),
        None,
        "no slow-down deadline stands for it"
    );
}

#[test]
fn a_non_portable_request_of_the_moved_pin_is_held_for_the_rewrite() {
    let (s, mut st, moved_at) = moved_to_b(vec![("a", 0), ("b", 1)]);
    let bound = SelectRequest {
        portable: false,
        ..turn_of(&s, "r-2", moved_at + 200)
    };
    let d = decide(&mut st, &s, &bound, &mut rng());
    let (account_id, hold) = held_on(&d);
    assert_eq!(
        (
            account_id.as_str(),
            hold.reason,
            hold.waits_for.as_deref(),
            hold.until
        ),
        (
            "b",
            HoldReason::Rewrite,
            Some("r-1"),
            Some(rewrite_bound(moved_at))
        )
    );
    assert!(
        !steps(&d.record).iter().any(|(step, _)| *step == "bound"),
        "the hold comes before the bound renewal: {:?}",
        steps(&d.record)
    );
    let count = SelectRequest {
        count: true,
        portable: false,
        ..turn_of(&s, "r-3", moved_at + 300)
    };
    let (result, _) = select(&mut st, &s, &count, &mut rng());
    assert_eq!(picked(&result), "b", "a count passes at the bound renewal");
}

#[test]
fn a_renewal_after_a_rewrite_wait_dates_the_pins_dispatch_at_the_release() {
    let (s, mut st, moved_at) = moved_to_b(vec![("a", 0), ("b", 1)]);
    let req = turn_of(&s, "r-2", moved_at + 200);
    let d = decide(&mut st, &s, &req, &mut rng());
    let (_, hold) = held_on(&d);
    assert_eq!(hold.reason, HoldReason::Rewrite);
    let gaps = st.pin_pace(&pin_key("s1")).expect("a pace").gaps;
    let released = SelectRequest {
        seq: 2,
        now: moved_at + 1_500,
        holds: vec![HoldFacts {
            held_ms: 1_300,
            ..hold
        }],
        ..req
    };
    let d = decide(&mut st, &s, &released, &mut rng());
    let SelectResult::Selected(ref sel) = d.result else {
        panic!("the request that waited renews, got {:?}", d.result)
    };
    assert!(sel.trace.renewed);
    assert_eq!(
        d.record.request.holds,
        vec![HoldFacts {
            account_id: "b".into(),
            cohort: None,
            held_ms: 1_300,
            attempt: 1,
            seq: 1,
            ran_out: false,
            reason: HoldReason::Rewrite,
            until: Some(rewrite_bound(moved_at)),
            waits_for: Some("r-1".into()),
        }]
    );
    assert_eq!(
        st.pin_pace(&pin_key("s1"))
            .map(|pace| (pace.dispatched_at, pace.gaps)),
        Some((moved_at + 1_500, gaps)),
        "the renewal dates the dispatch at the release and folds nothing"
    );
    assert_eq!(
        (d.summary.by.kind, d.summary.by.value.as_str()),
        ("hold", "rewrite")
    );
    assert_eq!(
        summary_facts(&d),
        vec![("held", FactValue::Int(1_300), Some("ms"))]
    );
    select(
        &mut st,
        &s,
        &turn_of(&s, "r-3", moved_at + 11_500),
        &mut rng(),
    );
    assert_eq!(
        st.pin_pace(&pin_key("s1"))
            .map(|pace| (pace.dispatched_at, pace.gaps)),
        Some((moved_at + 11_500, gaps + 1)),
        "the next gap is measured from the release"
    );
}

/// A main turn of `s1` on `model` under its own request id.
fn turn_on(s: &RegistrySnapshot, model: &str, request_id: &str, now: i64) -> SelectRequest {
    SelectRequest {
        request_id: request_id.into(),
        ..with_facts(
            request(s, Some("s1"), model, true, &[], now),
            Some("main"),
            false,
            None,
            &[],
        )
    }
}

/// `s1` placed on `a` under `claude-sonnet-5` at `T` by its request `r-1`, on a pool of `a` ahead of `b` whose hold
/// cap is `REWRITE_HOLD_SECONDS`.
fn sonnet_on_a() -> (RegistrySnapshot, RoutingState) {
    let s = snapshot(Pool {
        members: vec![("a", 0), ("b", 1)],
        slow_down: SlowDown {
            slow_down_hold_seconds: REWRITE_HOLD_SECONDS,
            ..SlowDown::default()
        },
        ..Pool::default()
    });
    let mut st = RoutingState::from_load(RoutingLoad::default());
    let (placed, _) = select(
        &mut st,
        &s,
        &turn_on(&s, "claude-sonnet-5", "r-1", T),
        &mut rng(),
    );
    assert_eq!((picked(&placed), left_of(&placed)), ("a", None));
    (s, st)
}

/// `a` cooled for `claude-opus-5` alone, so an opus turn lands on `b` while the sonnet pin on `a` stays eligible.
fn opus_cooled_on_a(st: &mut RoutingState) {
    st.record_cooldown(cooled(
        "a",
        "model:claude-opus-5",
        T + 10 * MINUTE,
        "retry_after",
        "rate_limit",
    ));
}

#[test]
fn a_session_that_switches_model_onto_another_account_names_the_account_it_left_and_holds_the_new_pins_next_request(
) {
    let (s, mut st) = sonnet_on_a();
    opus_cooled_on_a(&mut st);
    let switched_at = T + MINUTE;
    let (switched, _) = select(
        &mut st,
        &s,
        &turn_on(&s, "claude-opus-5", "r-2", switched_at),
        &mut rng(),
    );
    assert_eq!(
        (picked(&switched), left_of(&switched)),
        ("b", Some("a")),
        "the opus turn lands on b and names a, where the sonnet turn before it landed"
    );
    let d = decide(
        &mut st,
        &s,
        &turn_on(&s, "claude-opus-5", "r-3", switched_at + 200),
        &mut rng(),
    );
    let (account_id, hold) = held_on(&d);
    assert_eq!(
        (account_id.as_str(), hold.reason, hold.waits_for.as_deref()),
        ("b", HoldReason::Rewrite, Some("r-2")),
        "the new pin's next request waits for the landing's head"
    );
}

#[test]
fn a_session_that_switches_model_onto_the_same_account_names_none_and_marks_no_head() {
    let (s, mut st) = sonnet_on_a();
    let (switched, _) = select(
        &mut st,
        &s,
        &turn_on(&s, "claude-opus-5", "r-2", T + MINUTE),
        &mut rng(),
    );
    assert_eq!((picked(&switched), left_of(&switched)), ("a", None));
    let opus = PinKey {
        model: "claude-opus-5".into(),
        ..pin_key("s1")
    };
    assert_eq!(
        st.head_mark(&opus),
        None,
        "a landing on the account the session's previous turn landed on marks nothing"
    );
}

#[test]
fn a_return_to_a_models_live_pin_after_a_turn_on_another_account_names_that_account_and_the_next_turn_none(
) {
    let (s, mut st) = sonnet_on_a();
    opus_cooled_on_a(&mut st);
    let (switched, _) = select(
        &mut st,
        &s,
        &turn_on(&s, "claude-opus-5", "r-2", T + MINUTE),
        &mut rng(),
    );
    assert_eq!(picked(&switched), "b");
    let (returned, _) = select(
        &mut st,
        &s,
        &turn_on(&s, "claude-sonnet-5", "r-3", T + 2 * MINUTE),
        &mut rng(),
    );
    let SelectResult::Selected(ref sel) = returned else {
        panic!("the sonnet pin on a is live, got {returned:?}")
    };
    assert!(sel.trace.renewed, "the return renews the sonnet pin");
    assert_eq!(
        (picked(&returned), left_of(&returned)),
        ("a", Some("b")),
        "the renewal names b, where the opus turn before it landed"
    );
    let (next, _) = select(
        &mut st,
        &s,
        &turn_on(&s, "claude-sonnet-5", "r-4", T + 3 * MINUTE),
        &mut rng(),
    );
    assert_eq!(
        (picked(&next), left_of(&next)),
        ("a", None),
        "the turn after the return follows a turn on a"
    );
}

#[test]
fn an_auxiliary_call_on_another_model_that_landed_elsewhere_is_no_previous_landing_of_the_sessions_main_turn(
) {
    let (s, mut st) = sonnet_on_a();
    opus_cooled_on_a(&mut st);
    let call = SelectRequest {
        request_id: "r-2".into(),
        ..with_facts(
            request(&s, Some("s1"), "claude-opus-5", true, &[], T + MINUTE),
            Some("quota"),
            false,
            None,
            &[],
        )
    };
    let (placed, _) = select(&mut st, &s, &call, &mut rng());
    assert_eq!(
        (picked(&placed), left_of(&placed)),
        ("b", None),
        "the auxiliary call reads its own model's row alone"
    );
    let (renewed, _) = select(
        &mut st,
        &s,
        &turn_on(&s, "claude-sonnet-5", "r-3", T + 2 * MINUTE),
        &mut rng(),
    );
    let SelectResult::Selected(ref sel) = renewed else {
        panic!("the sonnet pin on a is live, got {renewed:?}")
    };
    assert!(sel.trace.renewed);
    assert_eq!(
        (picked(&renewed), left_of(&renewed)),
        ("a", None),
        "the main turn's previous landing is the sonnet turn's on a"
    );
}

#[test]
fn a_failovers_landing_after_a_model_switch_names_the_failovers_source_over_an_older_row_of_another_model(
) {
    let (s, mut st) = sonnet_on_a();
    // a refuses opus until just before the failover, so the opus turn lands on b and the failover's landing on a.
    let failed_at = T + MINUTE + 1_000;
    st.record_cooldown(cooled(
        "a",
        "model:claude-opus-5",
        failed_at - 500,
        "retry_after",
        "rate_limit",
    ));
    let switch = turn_on(&s, "claude-opus-5", "r-2", T + MINUTE);
    let (switched, _) = select(&mut st, &s, &switch, &mut rng());
    let SelectResult::Selected(ref sel) = switched else {
        panic!("the opus turn lands, got {switched:?}")
    };
    assert_eq!(picked(&switched), "b");
    let pin = sel.pin.clone().expect("the opus turn pins");
    let row = st
        .invalidate_pin(&pin, "b")
        .expect("the failover takes the opus row off b");
    let landing = SelectRequest {
        attempt: 2,
        seq: 2,
        attempted: vec!["b".into()],
        failed_over: Some(FailedOver {
            from_account_id: "b".into(),
            reason: "cooldown",
            row,
            cause: None,
        }),
        now: failed_at,
        received_at: failed_at,
        ..switch
    };
    let (landed, _) = select(&mut st, &s, &landing, &mut rng());
    assert_eq!(
        (picked(&landed), left_of(&landed)),
        ("a", Some("b")),
        "the landing names b, the failover's source, over the older sonnet row on a"
    );
    let opus = PinKey {
        model: "claude-opus-5".into(),
        ..pin_key("s1")
    };
    assert_eq!(
        st.head_mark(&opus)
            .map(|mark| (mark.request_id.as_str(), mark.attempt)),
        Some(("r-2", 2)),
        "the landing's write holds the opus pin's next request for its head"
    );
}

#[test]
fn a_renewal_after_a_hold_carries_the_wait_it_followed_in_its_trace_and_outcome() {
    let (s, mut st, moved_at) = moved_to_b(vec![("a", 0), ("b", 1)]);
    let req = turn_of(&s, "r-2", moved_at + 200);
    let (_, hold) = held_on(&decide(&mut st, &s, &req, &mut rng()));
    let released = SelectRequest {
        seq: 2,
        now: moved_at + 1_500,
        holds: vec![HoldFacts {
            held_ms: 1_300,
            ..hold
        }],
        ..req
    };
    let d = decide(&mut st, &s, &released, &mut rng());
    let SelectResult::Selected(ref sel) = d.result else {
        panic!("the request that waited renews, got {:?}", d.result)
    };
    assert!(sel.trace.renewed);
    assert_eq!(
        sel.trace.cohort_hold.as_ref().map(|carried| (
            carried.held_ms,
            carried.waits.iter().map(|w| w.reason).collect::<Vec<_>>()
        )),
        Some((1_300, vec![HoldReason::Rewrite])),
        "the renewal's trace carries the rewrite wait"
    );
    assert_eq!(
        d.record.outcome.cohort_hold, sel.trace.cohort_hold,
        "the record's outcome reads the trace's"
    );
}

#[test]
fn a_renewal_without_a_hold_carries_no_cohort_hold() {
    let (s, mut st) = sonnet_on_a();
    let d = decide(
        &mut st,
        &s,
        &turn_on(&s, "claude-sonnet-5", "r-2", T + MINUTE),
        &mut rng(),
    );
    let SelectResult::Selected(ref sel) = d.result else {
        panic!("the sonnet pin on a is live, got {:?}", d.result)
    };
    assert!(sel.trace.renewed);
    assert_eq!(
        (
            sel.trace.cohort_hold.as_ref(),
            d.record.outcome.cohort_hold.as_ref()
        ),
        (None, None)
    );
}

/// An Opus turn of `session` under `agent` and `class`, with `attempted` so a case steers where it lands.
fn opus_turn(
    s: &RegistrySnapshot,
    session: &str,
    agent: &str,
    class: &str,
    attempted: &[&str],
    now: i64,
) -> SelectRequest {
    SelectRequest {
        agent_id: agent.into(),
        ..with_facts(
            request(s, Some(session), "claude-opus-5-5", true, attempted, now),
            Some(class),
            false,
            None,
            &[],
        )
    }
}

/// `req` under the agent the routing task routes it as before its selection (`routed_agent`): the judged turn's agent
/// for a classifier call, its own for every other request.
fn routed(st: &RoutingState, req: SelectRequest) -> SelectRequest {
    match routed_agent(st, &req) {
        Some(agent_id) => SelectRequest { agent_id, ..req },
        None => req,
    }
}

/// The client's marked classifier call of `session`, as the client sends it: an auxiliary call on Sonnet 5 under
/// `main`, whatever agent's turn it judges.
fn classifier_call(s: &RegistrySnapshot, session: &str, now: i64) -> SelectRequest {
    SelectRequest {
        classifier: true,
        ..with_facts(
            request(s, Some(session), "claude-sonnet-5", true, &[], now),
            Some("auxiliary"),
            false,
            None,
            &[],
        )
    }
}

#[test]
fn a_classifier_call_follows_the_sessions_turn_that_ended_last_onto_its_account() {
    let s = snapshot(Pool {
        members: vec![("a", 0), ("b", 1)],
        ..Pool::default()
    });
    let mut st = RoutingState::from_load(RoutingLoad::default());
    let mut r = rng();
    let main_turn = opus_turn(&s, "s1", "main", "main", &[], 1_000);
    assert_eq!(picked(&select(&mut st, &s, &main_turn, &mut r).0), "a");
    let sub_turn = opus_turn(&s, "s1", "x", "subagent", &["a"], 2_000);
    assert_eq!(picked(&select(&mut st, &s, &sub_turn, &mut r).0), "b");
    // A plain auxiliary call of the session takes the strategy's pick, whatever turn ended last.
    let plain = SelectRequest {
        classifier: false,
        ..classifier_call(&s, "s1", 2_500)
    };
    assert_eq!(picked(&select(&mut st, &s, &plain, &mut r).0), "a");
    // The classifier call follows the subagent's turn, under the subagent's own pin on the classifier's model.
    let call = routed(&st, classifier_call(&s, "s1", 2_600));
    assert_eq!(picked(&select(&mut st, &s, &call, &mut r).0), "b");
    assert_eq!(pinned_agent(&st, "s1", "x").account_id, "b");
    // The main agent's next turn ends last, so the next call follows it onto the main's own Sonnet 5 pin.
    let main_turn = opus_turn(&s, "s1", "main", "main", &[], 3_000);
    select(&mut st, &s, &main_turn, &mut r);
    let call = routed(&st, classifier_call(&s, "s1", 3_100));
    assert_eq!(picked(&select(&mut st, &s, &call, &mut r).0), "a");
    assert_eq!(pinned(&st, "s1").account_id, "a");
}

#[test]
fn a_classifier_call_whose_judged_account_cannot_serve_it_lands_like_any_request_and_follows_once_it_can(
) {
    let s = snapshot(Pool {
        members: vec![("a", 0), ("b", 1)],
        ..Pool::default()
    });
    let mut st = RoutingState::from_load(RoutingLoad::default());
    let mut r = rng();
    let main_turn = opus_turn(&s, "s1", "main", "main", &[], 1_000);
    select(&mut st, &s, &main_turn, &mut r);
    let sub_turn = opus_turn(&s, "s1", "x", "subagent", &["a"], 2_000);
    assert_eq!(picked(&select(&mut st, &s, &sub_turn, &mut r).0), "b");
    // b cools after the subagent's turn: the call cannot follow it and lands by the strategy.
    st.record_cooldown(cooled("b", "account", 5_000, "five_hour", "rate_limit"));
    let call = routed(&st, classifier_call(&s, "s1", 2_600));
    assert_eq!(picked(&select(&mut st, &s, &call, &mut r).0), "a");
    assert_eq!(pinned_agent(&st, "s1", "x").account_id, "a");
    // Once b serves again, the next call follows the judged turn and its pin goes there.
    let call = routed(&st, classifier_call(&s, "s1", 6_000));
    assert_eq!(picked(&select(&mut st, &s, &call, &mut r).0), "b");
    assert_eq!(pinned_agent(&st, "s1", "x").account_id, "b");
}

#[test]
fn a_classifier_call_whose_judged_account_is_spent_lands_like_any_request() {
    let s = snapshot(Pool {
        members: vec![("a", 0), ("b", 1)],
        ..Pool::default()
    });
    let mut st = RoutingState::from_load(RoutingLoad::default());
    let mut r = rng();
    let main_turn = opus_turn(&s, "s1", "main", "main", &[], 1_000);
    select(&mut st, &s, &main_turn, &mut r);
    let sub_turn = opus_turn(&s, "s1", "x", "subagent", &["a"], 2_000);
    assert_eq!(picked(&select(&mut st, &s, &sub_turn, &mut r).0), "b");
    // b's 5-hour window reads spent after the subagent's turn: b stays eligible but holds no allowance.
    st.record_sample("b", refreshing(1.0, HOUR, 2 * HOUR, 2_000), 1);
    let call = routed(&st, classifier_call(&s, "s1", 2_600));
    assert_eq!(picked(&select(&mut st, &s, &call, &mut r).0), "a");
    assert_eq!(pinned_agent(&st, "s1", "x").account_id, "a");
}
